  const vision = 560 + r('eyes') * 70 + r('echo') * 90 + r('biolum') * 40 + (stage - 1) * 22;
  const regen = r('regen') * 0.35 + r('ascendant') * 0.2;
  const foodValue = 1 + r('digestion') * 0.18;
  const thirstRate = 1 - r('watersacs') * 0.17;
