cat > /tmp/opencode/startprobe.mjs <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
let ok=0, fail=0, reasons={};
for (let i=0;i<12;i++) {
  const page = await browser.newPage({ viewport: { width:1440, height:900 } });
  await page.goto('http://127.0.0.1:3002', { waitUntil:'load', timeout:45000 });
  await page.waitForFunction(()=>document.fonts.status==='loaded');
  const candidate = page.locator('button, input[type="button"], input[type="submit"], [role="button"]');
  const t=Date.now(); let reason='clicked';
  const deadline=Date.now()+3000;
  do {
    const matches=[];
    for (const control of await candidate.all()) {
      if (!await control.isVisible() || !await control.isEnabled()) continue;
      const eligible=await control.evaluate((element, explicit)=>{
        if (element.closest('a[href], form') || element.getAttribute('aria-disabled')==='true') return false;
        if (explicit) return true;
        const label=element.getAttribute('aria-label')||element.value||element.textContent||'';
        return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim());
      }, false);
      if (eligible) matches.push(control);
    }
    if (matches.length>1){reason='ambiguous';break;}
    if (matches.length===1){
      try{await matches[0].click({trial:true,timeout:2000});}
      catch(e){ if(e.name==='TimeoutError'){reason='not-actionable';break;} throw e; }
      await matches[0].click({timeout:2000,noWaitAfter:true});
      reason='clicked'; break;
    }
    if(Date.now()>=deadline){reason='not-found';break;}
    await page.waitForTimeout(200);
  } while(Date.now()<=deadline);
  if(reason==='clicked') ok++; else {fail++; reasons[reason]=(reasons[reason]||0)+1;}
  console.log(i, reason, Date.now()-t+'ms', await page.evaluate(()=>window.sporeGenesis.started));
  await page.close();
}
console.log('ok',ok,'fail',fail,reasons);
await browser.close();
EOF
